// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    Reverter receiver;

    function setUp() public {
        c = new MyContract();
        receiver = new Reverter();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        // fund the contract so the amount is admissible (transfer would not fail for lack of balance)
        vm.deal(address(c), amount);

        uint256 recvBefore = address(receiver).balance;

        // owner is the deployer (this test contract)
        vm.prank(address(this));
        bool ok;
        try c.sendTo(address(receiver), amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a sendTo that completes without reverting must have delivered
        // exactly `amount` to the receiver. Reference: rejecting receiver forces a
        // revert, so ok is always false and the rule holds. Mutant: unchecked send
        // swallows the failure, call succeeds (ok == true) yet nothing is delivered.
        assertTrue(!ok || (address(receiver).balance == recvBefore + amount));
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
